window.LEX_LIBRARY.questions.push(...[{"id": "lawtext-B0000001-1135-1", "subject": "親屬法", "topic": "期間・數額・比例・§1135", "kind": "法條", "question": "【法條原文辨識】依《民法》第1135條，下列節錄的【空格】應填入何者？\n\n「親屬會議，非有【空格】以上之出席，不得開會；非有出席會員過半數之同意，不得為決議。」", "options": ["一人", "五人", "三人", "二人"], "answer": 2, "explanations": ["此處不是「一人」。民法第1135條在本題位置規定的是「三人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「五人」。民法第1135條在本題位置規定的是「三人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1135條此處原文是「三人」。\n原句：親屬會議，非有三人以上之出席，不得開會；非有出席會員過半數之同意，不得為決議。", "此處不是「二人」。民法第1135條在本題位置規定的是「三人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1135條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1135", "text": "親屬會議，非有三人以上之出席，不得開會；非有出席會員過半數之同意，不得為決議。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1113-5-2", "subject": "親屬法", "topic": "期間・數額・比例・§1113-5", "kind": "法條", "question": "【法條原文辨識】依《民法》第1113-5條，下列節錄的【空格】應填入何者？\n\n「意定監護契約之撤回，應以書面先向他方為之，並由公證人作成公證書後，始生撤回之效力。公證人作成公證書後【空格】內，以書面通知本人住所地之法院。契約經一部撤回者，視為全部撤回。」", "options": ["七日", "三日", "五日", "十日"], "answer": 0, "explanations": ["正確。民法第1113-5條此處原文是「七日」。\n原句：意定監護契約之撤回，應以書面先向他方為之，並由公證人作成公證書後，始生撤回之效力。公證人作成公證書後七日內，以書面通知本人住所地之法院。契約經一部撤回者，視為全部撤回。", "此處不是「三日」。民法第1113-5條在本題位置規定的是「七日」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「五日」。民法第1113-5條在本題位置規定的是「七日」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「十日」。民法第1113-5條在本題位置規定的是「七日」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1113-5條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1113-5", "text": "法院為監護之宣告前，意定監護契約之本人或受任人得隨時撤回之。\n意定監護契約之撤回，應以書面先向他方為之，並由公證人作成公證書後，始生撤回之效力。公證人作成公證書後七日內，以書面通知本人住所地之法院。契約經一部撤回者，視為全部撤回。\n法院為監護之宣告後，本人有正當理由者，得聲請法院許可終止意定監護契約。受任人有正當理由者，得聲請法院許可辭任其職務。\n法院依前項許可終止意定監護契約時，應依職權就第一千一百十一條第一項所列之人選定為監護人。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1090-1", "subject": "親屬法", "topic": "親屬與繼承・§1090", "kind": "法條", "question": "【法條原文辨識】依《民法》第1090條，下列節錄的【空格】應填入何者？\n\n「父母之一方濫用其對於子女之權利時，【空格】得依他方、未成年子女、主管機關、社會福利機構或其他利害關係人之請求或依職權，為子女之利益，宣告停止其權利之全部或一部。」", "options": ["法院", "親屬會議", "檢察官", "戶政機關"], "answer": 0, "explanations": ["正確。民法第1090條此處原文是「法院」。\n原句：父母之一方濫用其對於子女之權利時，法院得依他方、未成年子女、主管機關、社會福利機構或其他利害關係人之請求或依職權，為子女之利益，宣告停止其權利之全部或一部。", "此處不是「親屬會議」。民法第1090條在本題位置規定的是「法院」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「檢察官」。民法第1090條在本題位置規定的是「法院」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「戶政機關」。民法第1090條在本題位置規定的是「法院」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1090條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1090", "text": "父母之一方濫用其對於子女之權利時，法院得依他方、未成年子女、主管機關、社會福利機構或其他利害關係人之請求或依職權，為子女之利益，宣告停止其權利之全部或一部。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1092-1", "subject": "親屬法", "topic": "親屬與繼承・§1092", "kind": "法條", "question": "【法條原文辨識】依《民法》第1092條，下列節錄的【空格】應填入何者？\n\n「【空格】對其未成年之子女，得因特定事項，於一定期限內，以書面委託他人行使監護之職務。」", "options": ["祖父母", "直系血親卑親屬", "兄弟姊妹", "父母"], "answer": 3, "explanations": ["此處不是「祖父母」。民法第1092條在本題位置規定的是「父母」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「直系血親卑親屬」。民法第1092條在本題位置規定的是「父母」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「兄弟姊妹」。民法第1092條在本題位置規定的是「父母」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1092條此處原文是「父母」。\n原句：父母對其未成年之子女，得因特定事項，於一定期限內，以書面委託他人行使監護之職務。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1092條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1092", "text": "父母對其未成年之子女，得因特定事項，於一定期限內，以書面委託他人行使監護之職務。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-996-1", "subject": "親屬法", "topic": "期間・數額・比例・§996", "kind": "法條", "question": "【法條原文辨識】依《民法》第996條，下列節錄的【空格】應填入何者？\n\n「當事人之一方，於結婚時係在無意識或精神錯亂中者，得於常態回復後【空格】內向法院請求撤銷之。」", "options": ["一個月", "六個月", "二個月", "三個月"], "answer": 1, "explanations": ["此處不是「一個月」。民法第996條在本題位置規定的是「六個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第996條此處原文是「六個月」。\n原句：當事人之一方，於結婚時係在無意識或精神錯亂中者，得於常態回復後六個月內向法院請求撤銷之。", "此處不是「二個月」。民法第996條在本題位置規定的是「六個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「三個月」。民法第996條在本題位置規定的是「六個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第996條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=996", "text": "當事人之一方，於結婚時係在無意識或精神錯亂中者，得於常態回復後六個月內向法院請求撤銷之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1131-1", "subject": "親屬法", "topic": "親屬與繼承・§1131", "kind": "法條", "question": "【法條原文辨識】依《民法》第1131條，下列節錄的【空格】應填入何者？\n\n「親屬會議會員，應就未成年人、受【空格】宣告之人或被繼承人之下列親屬與順序定之：」", "options": ["訂婚", "監護", "認領", "收養"], "answer": 1, "explanations": ["此處不是「訂婚」。民法第1131條在本題位置規定的是「監護」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1131條此處原文是「監護」。\n原句：親屬會議會員，應就未成年人、受監護宣告之人或被繼承人之下列親屬與順序定之：", "此處不是「認領」。民法第1131條在本題位置規定的是「監護」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「收養」。民法第1131條在本題位置規定的是「監護」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1131條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1131", "text": "親屬會議會員，應就未成年人、受監護宣告之人或被繼承人之下列親屬與順序定之：\n一、直系血親尊親屬。\n二、三親等內旁系血親尊親屬。\n三、四親等內之同輩血親。\n前項同一順序之人，以親等近者為先；親等同者，以同居親屬為先，無同居親屬者，以年長者為先。\n依前二項順序所定之親屬會議會員，不能出席會議或難於出席時，由次順序之親屬充任之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1130-1", "subject": "親屬法", "topic": "期間・數額・比例・§1130", "kind": "法條", "question": "【法條原文辨識】依《民法》第1130條，下列節錄的【空格】應填入何者？\n\n「親屬會議，以會員【空格】組織之。」", "options": ["三人", "二人", "五人", "一人"], "answer": 2, "explanations": ["此處不是「三人」。民法第1130條在本題位置規定的是「五人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「二人」。民法第1130條在本題位置規定的是「五人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1130條此處原文是「五人」。\n原句：親屬會議，以會員五人組織之。", "此處不是「一人」。民法第1130條在本題位置規定的是「五人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1130條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1130", "text": "親屬會議，以會員五人組織之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1061-1", "subject": "親屬法", "topic": "親屬與繼承・§1061", "kind": "法條", "question": "【法條原文辨識】依《民法》第1061條，下列節錄的【空格】應填入何者？\n\n「稱【空格】者，謂由婚姻關係受胎而生之子女。」", "options": ["婚生子女", "非婚生子女", "養子女", "繼子女"], "answer": 0, "explanations": ["正確。民法第1061條此處原文是「婚生子女」。\n原句：稱婚生子女者，謂由婚姻關係受胎而生之子女。", "此處不是「非婚生子女」。民法第1061條在本題位置規定的是「婚生子女」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「養子女」。民法第1061條在本題位置規定的是「婚生子女」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「繼子女」。民法第1061條在本題位置規定的是「婚生子女」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1061條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1061", "text": "稱婚生子女者，謂由婚姻關係受胎而生之子女。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1067-1", "subject": "親屬法", "topic": "行政程序・§1067", "kind": "法條", "question": "【法條原文辨識】依《民法》第1067條，下列節錄的【空格】應填入何者？\n\n「有事實足認其為非婚生子女之生父者，非婚生子女或其生母或其他法定【空格】人，得向生父提起認領之訴。」", "options": ["委任", "代理", "委託", "委辦"], "answer": 1, "explanations": ["此處不是「委任」。民法第1067條在本題位置規定的是「代理」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1067條此處原文是「代理」。\n原句：有事實足認其為非婚生子女之生父者，非婚生子女或其生母或其他法定代理人，得向生父提起認領之訴。", "此處不是「委託」。民法第1067條在本題位置規定的是「代理」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「委辦」。民法第1067條在本題位置規定的是「代理」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是行政程序，再核對條件與例外。", "sources": [{"title": "民法第1067條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1067", "text": "有事實足認其為非婚生子女之生父者，非婚生子女或其生母或其他法定代理人，得向生父提起認領之訴。\n前項認領之訴，於生父死亡後，得向生父之繼承人為之。生父無繼承人者，得向社會福利主管機關為之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1132-4", "subject": "親屬法", "topic": "親屬與繼承・§1132", "kind": "法條", "question": "【法條原文辨識】依《民法》第1132條，下列節錄的【空格】應填入何者？\n\n「三、【空格】經召開而不為或不能決議。」", "options": ["法院", "親屬會議", "戶政機關", "檢察官"], "answer": 1, "explanations": ["此處不是「法院」。民法第1132條在本題位置規定的是「親屬會議」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1132條此處原文是「親屬會議」。\n原句：三、親屬會議經召開而不為或不能決議。", "此處不是「戶政機關」。民法第1132條在本題位置規定的是「親屬會議」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「檢察官」。民法第1132條在本題位置規定的是「親屬會議」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1132條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1132", "text": "依法應經親屬會議處理之事項，而有下列情形之一者，得由有召集權人或利害關係人聲請法院處理之：\n一、無前條規定之親屬或親屬不足法定人數。\n二、親屬會議不能或難以召開。\n三、親屬會議經召開而不為或不能決議。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1101-1", "subject": "親屬法", "topic": "行政程序・§1101", "kind": "法條", "question": "【法條原文辨識】依《民法》第1101條，下列節錄的【空格】應填入何者？\n\n「監護人對於受監護人之財產，非為受監護人之利益，不得使用、代為或同意【空格】。」", "options": ["指導", "處分", "契約", "陳情"], "answer": 1, "explanations": ["此處不是「指導」。民法第1101條在本題位置規定的是「處分」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1101條此處原文是「處分」。\n原句：監護人對於受監護人之財產，非為受監護人之利益，不得使用、代為或同意處分。", "此處不是「契約」。民法第1101條在本題位置規定的是「處分」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「陳情」。民法第1101條在本題位置規定的是「處分」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是行政程序，再核對條件與例外。", "sources": [{"title": "民法第1101條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1101", "text": "監護人對於受監護人之財產，非為受監護人之利益，不得使用、代為或同意處分。\n監護人為下列行為，非經法院許可，不生效力：\n一、代理受監護人購置或處分不動產。\n二、代理受監護人，就供其居住之建築物或其基地出租、供他人使用或終止租賃。\n監護人不得以受監護人之財產為投資。但購買公債、國庫券、中央銀行儲蓄券、金融債券、可轉讓定期存單、金融機構承兌匯票或保證商業本票，不在此限。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-977-1", "subject": "親屬法", "topic": "法律效果・§977", "kind": "法條", "question": "【法條原文辨識】依《民法》第977條，下列節錄的【空格】應填入何者？\n\n「依前條之規定，婚約【空格】時，無過失之一方，得向有過失之他方，請求賠償其因此所受之損害。」", "options": ["撤銷", "終止", "變更", "解除"], "answer": 3, "explanations": ["此處不是「撤銷」。民法第977條在本題位置規定的是「解除」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「終止」。民法第977條在本題位置規定的是「解除」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「變更」。民法第977條在本題位置規定的是「解除」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第977條此處原文是「解除」。\n原句：依前條之規定，婚約解除時，無過失之一方，得向有過失之他方，請求賠償其因此所受之損害。"], "hint": "先判斷空格要填的是法律效果，再核對條件與例外。", "sources": [{"title": "民法第977條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=977", "text": "依前條之規定，婚約解除時，無過失之一方，得向有過失之他方，請求賠償其因此所受之損害。\n前項情形，雖非財產上之損害，受害人亦得請求賠償相當之金額。\n前項請求權不得讓與或繼承。但已依契約承諾，或已起訴者，不在此限。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1119-1", "subject": "親屬法", "topic": "憲政原則・§1119", "kind": "法條", "question": "【法條原文辨識】依《民法》第1119條，下列節錄的【空格】應填入何者？\n\n「扶養之程度，應按受扶養權利者之需要，與負扶養【空格】者之經濟能力及身分定之。」", "options": ["資格", "責任", "義務", "自由"], "answer": 2, "explanations": ["此處不是「資格」。民法第1119條在本題位置規定的是「義務」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「責任」。民法第1119條在本題位置規定的是「義務」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1119條此處原文是「義務」。\n原句：扶養之程度，應按受扶養權利者之需要，與負扶養義務者之經濟能力及身分定之。", "此處不是「自由」。民法第1119條在本題位置規定的是「義務」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是憲政原則，再核對條件與例外。", "sources": [{"title": "民法第1119條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1119", "text": "扶養之程度，應按受扶養權利者之需要，與負扶養義務者之經濟能力及身分定之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1082-1", "subject": "親屬法", "topic": "法律效果・§1082", "kind": "法條", "question": "【法條原文辨識】依《民法》第1082條，下列節錄的【空格】應填入何者？\n\n「因收養關係【空格】而生活陷於困難者，得請求他方給與相當之金額。但其請求顯失公平者，得減輕或免除之。」", "options": ["撤銷", "解除", "終止", "變更"], "answer": 2, "explanations": ["此處不是「撤銷」。民法第1082條在本題位置規定的是「終止」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「解除」。民法第1082條在本題位置規定的是「終止」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1082條此處原文是「終止」。\n原句：因收養關係終止而生活陷於困難者，得請求他方給與相當之金額。但其請求顯失公平者，得減輕或免除之。", "此處不是「變更」。民法第1082條在本題位置規定的是「終止」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是法律效果，再核對條件與例外。", "sources": [{"title": "民法第1082條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1082", "text": "因收養關係終止而生活陷於困難者，得請求他方給與相當之金額。但其請求顯失公平者，得減輕或免除之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1059-1-4", "subject": "親屬法", "topic": "期間・數額・比例・§1059-1", "kind": "法條", "question": "【法條原文辨識】依《民法》第1059-1條，下列節錄的【空格】應填入何者？\n\n「二、父母之一方或雙方生死不明滿【空格】者。」", "options": ["三年", "二年", "五年", "一年"], "answer": 0, "explanations": ["正確。民法第1059-1條此處原文是「三年」。\n原句：二、父母之一方或雙方生死不明滿三年者。", "此處不是「二年」。民法第1059-1條在本題位置規定的是「三年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「五年」。民法第1059-1條在本題位置規定的是「三年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「一年」。民法第1059-1條在本題位置規定的是「三年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1059-1條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1059-1", "text": "非婚生子女從母姓。經生父認領者，適用前條第二項至第四項之規定。\n非婚生子女經生父認領，而有下列各款情形之一，法院得依父母之一方或子女之請求，為子女之利益，宣告變更子女之姓氏為父姓或母姓：\n一、父母之一方或雙方死亡者。\n二、父母之一方或雙方生死不明滿三年者。\n三、子女之姓氏與任權利義務行使或負擔之父或母不一致者。\n四、父母之一方顯有未盡保護或教養義務之情事者。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1086-1", "subject": "親屬法", "topic": "行政程序・§1086", "kind": "法條", "question": "【法條原文辨識】依《民法》第1086條，下列節錄的【空格】應填入何者？\n\n「父母為其未成年子女之法定【空格】人。」", "options": ["代理", "委託", "委辦", "委任"], "answer": 0, "explanations": ["正確。民法第1086條此處原文是「代理」。\n原句：父母為其未成年子女之法定代理人。", "此處不是「委託」。民法第1086條在本題位置規定的是「代理」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「委辦」。民法第1086條在本題位置規定的是「代理」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「委任」。民法第1086條在本題位置規定的是「代理」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是行政程序，再核對條件與例外。", "sources": [{"title": "民法第1086條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1086", "text": "父母為其未成年子女之法定代理人。\n父母之行為與未成年子女之利益相反，依法不得代理時，法院得依父母、未成年子女、主管機關、社會福利機構或其他利害關係人之聲請或依職權，為子女選任特別代理人。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1097-3", "subject": "親屬法", "topic": "親屬與繼承・§1097", "kind": "法條", "question": "【法條原文辨識】依《民法》第1097條，下列節錄的【空格】應填入何者？\n\n「法院為前項裁判前，應聽取受【空格】人、主管機關或社會福利機構之意見。」", "options": ["收養", "訂婚", "認領", "監護"], "answer": 3, "explanations": ["此處不是「收養」。民法第1097條在本題位置規定的是「監護」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「訂婚」。民法第1097條在本題位置規定的是「監護」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「認領」。民法第1097條在本題位置規定的是「監護」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1097條此處原文是「監護」。\n原句：法院為前項裁判前，應聽取受監護人、主管機關或社會福利機構之意見。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1097條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1097", "text": "除另有規定外，監護人於保護、增進受監護人利益之範圍內，行使、負擔父母對於未成年子女之權利、義務。但由父母暫時委託者，以所委託之職務為限。\n監護人有數人，對於受監護人重大事項權利之行使意思不一致時，得聲請法院依受監護人之最佳利益，酌定由其中一監護人行使之。\n法院為前項裁判前，應聽取受監護人、主管機關或社會福利機構之意見。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1052-1-1", "subject": "親屬法", "topic": "債的效力・§1052-1", "kind": "法條", "question": "【法條原文辨識】依《民法》第1052-1條，下列節錄的【空格】應填入何者？\n\n「離婚經法院調解或法院和解成立者，婚姻關係消滅。法院應依職權【空格】該管戶政機關。」", "options": ["通知", "撤回", "承認", "拒絕"], "answer": 0, "explanations": ["正確。民法第1052-1條此處原文是「通知」。\n原句：離婚經法院調解或法院和解成立者，婚姻關係消滅。法院應依職權通知該管戶政機關。", "此處不是「撤回」。民法第1052-1條在本題位置規定的是「通知」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「承認」。民法第1052-1條在本題位置規定的是「通知」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「拒絕」。民法第1052-1條在本題位置規定的是「通知」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是債的效力，再核對條件與例外。", "sources": [{"title": "民法第1052-1條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1052-1", "text": "離婚經法院調解或法院和解成立者，婚姻關係消滅。法院應依職權通知該管戶政機關。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1057-1", "subject": "親屬法", "topic": "親屬與繼承・§1057", "kind": "法條", "question": "【法條原文辨識】依《民法》第1057條，下列節錄的【空格】應填入何者？\n\n「夫妻無過失之一方，因判決【空格】而陷於生活困難者，他方縱無過失，亦應給與相當之贍養費。」", "options": ["收養", "婚約", "結婚", "離婚"], "answer": 3, "explanations": ["此處不是「收養」。民法第1057條在本題位置規定的是「離婚」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「婚約」。民法第1057條在本題位置規定的是「離婚」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「結婚」。民法第1057條在本題位置規定的是「離婚」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1057條此處原文是「離婚」。\n原句：夫妻無過失之一方，因判決離婚而陷於生活困難者，他方縱無過失，亦應給與相當之贍養費。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1057條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1057", "text": "夫妻無過失之一方，因判決離婚而陷於生活困難者，他方縱無過失，亦應給與相當之贍養費。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-982-1", "subject": "親屬法", "topic": "期間・數額・比例・§982", "kind": "法條", "question": "【法條原文辨識】依《民法》第982條，下列節錄的【空格】應填入何者？\n\n「結婚應以書面為之，有【空格】以上證人之簽名，並應由雙方當事人向戶政機關為結婚之登記。」", "options": ["五人", "三人", "二人", "一人"], "answer": 2, "explanations": ["此處不是「五人」。民法第982條在本題位置規定的是「二人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「三人」。民法第982條在本題位置規定的是「二人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第982條此處原文是「二人」。\n原句：結婚應以書面為之，有二人以上證人之簽名，並應由雙方當事人向戶政機關為結婚之登記。", "此處不是「一人」。民法第982條在本題位置規定的是「二人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第982條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=982", "text": "結婚應以書面為之，有二人以上證人之簽名，並應由雙方當事人向戶政機關為結婚之登記。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1117-2", "subject": "親屬法", "topic": "親屬與繼承・§1117", "kind": "法條", "question": "【法條原文辨識】依《民法》第1117條，下列節錄的【空格】應填入何者？\n\n「前項無謀生能力之限制，於【空格】尊親屬，不適用之。」", "options": ["旁系血親", "直系姻親", "直系血親", "旁系姻親"], "answer": 2, "explanations": ["此處不是「旁系血親」。民法第1117條在本題位置規定的是「直系血親」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「直系姻親」。民法第1117條在本題位置規定的是「直系血親」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1117條此處原文是「直系血親」。\n原句：前項無謀生能力之限制，於直系血親尊親屬，不適用之。", "此處不是「旁系姻親」。民法第1117條在本題位置規定的是「直系血親」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1117條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1117", "text": "受扶養權利者，以不能維持生活而無謀生能力者為限。\n前項無謀生能力之限制，於直系血親尊親屬，不適用之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1038-1", "subject": "親屬法", "topic": "債的效力・§1038", "kind": "法條", "question": "【法條原文辨識】依《民法》第1038條，下列節錄的【空格】應填入何者？\n\n「共同財產所負之債務，而以共同財產【空格】者，不生補償請求權。」", "options": ["提存", "混同", "抵銷", "清償"], "answer": 3, "explanations": ["此處不是「提存」。民法第1038條在本題位置規定的是「清償」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「混同」。民法第1038條在本題位置規定的是「清償」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「抵銷」。民法第1038條在本題位置規定的是「清償」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1038條此處原文是「清償」。\n原句：共同財產所負之債務，而以共同財產清償者，不生補償請求權。"], "hint": "先判斷空格要填的是債的效力，再核對條件與例外。", "sources": [{"title": "民法第1038條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1038", "text": "共同財產所負之債務，而以共同財產清償者，不生補償請求權。\n共同財產之債務，而以特有財產清償，或特有財產之債務，而以共同財產清償者，有補償請求權，雖於婚姻關係存續中，亦得請求。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1108-1", "subject": "親屬法", "topic": "親屬與繼承・§1108", "kind": "法條", "question": "【法條原文辨識】依《民法》第1108條，下列節錄的【空格】應填入何者？\n\n「監護人死亡時，前條移交及結算，由其繼承人為之；其無繼承人或繼承人有無不明者，由新監護人逕行辦理結算，連同依第一千零九十九條規定開具之財產清冊陳報【空格】。」", "options": ["檢察官", "親屬會議", "戶政機關", "法院"], "answer": 3, "explanations": ["此處不是「檢察官」。民法第1108條在本題位置規定的是「法院」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「親屬會議」。民法第1108條在本題位置規定的是「法院」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「戶政機關」。民法第1108條在本題位置規定的是「法院」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1108條此處原文是「法院」。\n原句：監護人死亡時，前條移交及結算，由其繼承人為之；其無繼承人或繼承人有無不明者，由新監護人逕行辦理結算，連同依第一千零九十九條規定開具之財產清冊陳報法院。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1108條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1108", "text": "監護人死亡時，前條移交及結算，由其繼承人為之；其無繼承人或繼承人有無不明者，由新監護人逕行辦理結算，連同依第一千零九十九條規定開具之財產清冊陳報法院。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1007-1", "subject": "親屬法", "topic": "行政程序・§1007", "kind": "法條", "question": "【法條原文辨識】依《民法》第1007條，下列節錄的【空格】應填入何者？\n\n「夫妻財產制契約之訂立、變更或廢止，應以【空格】為之。」", "options": ["言詞", "電子郵件", "書面", "公告"], "answer": 2, "explanations": ["此處不是「言詞」。民法第1007條在本題位置規定的是「書面」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「電子郵件」。民法第1007條在本題位置規定的是「書面」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1007條此處原文是「書面」。\n原句：夫妻財產制契約之訂立、變更或廢止，應以書面為之。", "此處不是「公告」。民法第1007條在本題位置規定的是「書面」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是行政程序，再核對條件與例外。", "sources": [{"title": "民法第1007條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1007", "text": "夫妻財產制契約之訂立、變更或廢止，應以書面為之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1040-1", "subject": "親屬法", "topic": "行政程序・§1040", "kind": "法條", "question": "【法條原文辨識】依《民法》第1040條，下列節錄的【空格】應填入何者？\n\n「共同財產制關係消滅時，除法律另有規定外，夫妻各取回其訂立共同財產制【空格】時之財產。」", "options": ["陳情", "契約", "指導", "處分"], "answer": 1, "explanations": ["此處不是「陳情」。民法第1040條在本題位置規定的是「契約」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1040條此處原文是「契約」。\n原句：共同財產制關係消滅時，除法律另有規定外，夫妻各取回其訂立共同財產制契約時之財產。", "此處不是「指導」。民法第1040條在本題位置規定的是「契約」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「處分」。民法第1040條在本題位置規定的是「契約」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是行政程序，再核對條件與例外。", "sources": [{"title": "民法第1040條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1040", "text": "共同財產制關係消滅時，除法律另有規定外，夫妻各取回其訂立共同財產制契約時之財產。\n共同財產制關係存續中取得之共同財產，由夫妻各得其半數。但另有約定者，從其約定。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-998-1", "subject": "親屬法", "topic": "法律效果・§998", "kind": "法條", "question": "【法條原文辨識】依《民法》第998條，下列節錄的【空格】應填入何者？\n\n「結婚撤銷之效力，【空格】。」", "options": ["溯及既往", "不溯及既往", "自始無效", "效力未定"], "answer": 1, "explanations": ["此處不是「溯及既往」。民法第998條在本題位置規定的是「不溯及既往」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第998條此處原文是「不溯及既往」。\n原句：結婚撤銷之效力，不溯及既往。", "此處不是「自始無效」。民法第998條在本題位置規定的是「不溯及既往」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「效力未定」。民法第998條在本題位置規定的是「不溯及既往」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是法律效果，再核對條件與例外。", "sources": [{"title": "民法第998條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=998", "text": "結婚撤銷之效力，不溯及既往。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1084-2", "subject": "親屬法", "topic": "親屬與繼承・§1084", "kind": "法條", "question": "【法條原文辨識】依《民法》第1084條，下列節錄的【空格】應填入何者？\n\n「【空格】對於未成年之子女，有保護及教養之權利義務。」", "options": ["父母", "祖父母", "直系血親卑親屬", "兄弟姊妹"], "answer": 0, "explanations": ["正確。民法第1084條此處原文是「父母」。\n原句：父母對於未成年之子女，有保護及教養之權利義務。", "此處不是「祖父母」。民法第1084條在本題位置規定的是「父母」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「直系血親卑親屬」。民法第1084條在本題位置規定的是「父母」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「兄弟姊妹」。民法第1084條在本題位置規定的是「父母」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1084條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1084", "text": "子女應孝敬父母。\n父母對於未成年之子女，有保護及教養之權利義務。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-999-1-2", "subject": "親屬法", "topic": "法律效果・§999-1", "kind": "法條", "question": "【法條原文辨識】依《民法》第999-1條，下列節錄的【空格】應填入何者？\n\n「第一千零五十五條、第一千零五十五條之一、第一千零五十五條之二、第一千零五十七條及第一千零五十八條之規定，於結婚經【空格】時準用之。」", "options": ["撤銷", "解除", "變更", "終止"], "answer": 0, "explanations": ["正確。民法第999-1條此處原文是「撤銷」。\n原句：第一千零五十五條、第一千零五十五條之一、第一千零五十五條之二、第一千零五十七條及第一千零五十八條之規定，於結婚經撤銷時準用之。", "此處不是「解除」。民法第999-1條在本題位置規定的是「撤銷」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「變更」。民法第999-1條在本題位置規定的是「撤銷」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「終止」。民法第999-1條在本題位置規定的是「撤銷」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是法律效果，再核對條件與例外。", "sources": [{"title": "民法第999-1條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=999-1", "text": "第一千零五十七條及第一千零五十八條之規定，於結婚無效時準用之。\n第一千零五十五條、第一千零五十五條之一、第一千零五十五條之二、第一千零五十七條及第一千零五十八條之規定，於結婚經撤銷時準用之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1080-3-1", "subject": "親屬法", "topic": "期間・數額・比例・§1080-3", "kind": "法條", "question": "【法條原文辨識】依《民法》第1080-3條，下列節錄的【空格】應填入何者？\n\n「終止收養，違反第一千零八十條第七項之規定者，終止收養者之配偶得請求法院撤銷之。但自知悉其事實之日起，已逾【空格】，或自法院認可之日起已逾一年者，不得請求撤銷。」", "options": ["二個月", "六個月", "三個月", "一個月"], "answer": 1, "explanations": ["此處不是「二個月」。民法第1080-3條在本題位置規定的是「六個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1080-3條此處原文是「六個月」。\n原句：終止收養，違反第一千零八十條第七項之規定者，終止收養者之配偶得請求法院撤銷之。但自知悉其事實之日起，已逾六個月，或自法院認可之日起已逾一年者，不得請求撤銷。", "此處不是「三個月」。民法第1080-3條在本題位置規定的是「六個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「一個月」。民法第1080-3條在本題位置規定的是「六個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1080-3條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1080-3", "text": "終止收養，違反第一千零八十條第七項之規定者，終止收養者之配偶得請求法院撤銷之。但自知悉其事實之日起，已逾六個月，或自法院認可之日起已逾一年者，不得請求撤銷。\n終止收養，違反第一千零八十條第六項或第一千零八十條之一第三項之規定者，終止收養後被收養者之法定代理人得請求法院撤銷之。但自知悉其事實之日起，已逾六個月，或自法院許可之日起已逾一年者，不得請求撤銷。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1023-2", "subject": "親屬法", "topic": "債的效力・§1023", "kind": "法條", "question": "【法條原文辨識】依《民法》第1023條，下列節錄的【空格】應填入何者？\n\n「夫妻之一方以自己財產【空格】他方之債務時，雖於婚姻關係存續中，亦得請求償還。」", "options": ["混同", "抵銷", "提存", "清償"], "answer": 3, "explanations": ["此處不是「混同」。民法第1023條在本題位置規定的是「清償」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「抵銷」。民法第1023條在本題位置規定的是「清償」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「提存」。民法第1023條在本題位置規定的是「清償」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1023條此處原文是「清償」。\n原句：夫妻之一方以自己財產清償他方之債務時，雖於婚姻關係存續中，亦得請求償還。"], "hint": "先判斷空格要填的是債的效力，再核對條件與例外。", "sources": [{"title": "民法第1023條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1023", "text": "夫妻各自對其債務負清償之責。\n夫妻之一方以自己財產清償他方之債務時，雖於婚姻關係存續中，亦得請求償還。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1111-2-1", "subject": "親屬法", "topic": "權利主體・§1111-2", "kind": "法條", "question": "【法條原文辨識】依《民法》第1111-2條，下列節錄的【空格】應填入何者？\n\n「照護受監護宣告之人之法人或機構及其代表人、負責人，或與該法人或機構有僱傭、委任或其他類似關係之人，不得為該受監護宣告之人之【空格】。但為該受監護宣告之人之配偶、四親等內之血親或二親等內之姻親者，不在此限。」", "options": ["法定代理人", "輔助人", "代理人", "監護人"], "answer": 3, "explanations": ["此處不是「法定代理人」。民法第1111-2條在本題位置規定的是「監護人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「輔助人」。民法第1111-2條在本題位置規定的是「監護人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「代理人」。民法第1111-2條在本題位置規定的是「監護人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1111-2條此處原文是「監護人」。\n原句：照護受監護宣告之人之法人或機構及其代表人、負責人，或與該法人或機構有僱傭、委任或其他類似關係之人，不得為該受監護宣告之人之監護人。但為該受監護宣告之人之配偶、四親等內之血親或二親等內之姻親者，不在此限。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第1111-2條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1111-2", "text": "照護受監護宣告之人之法人或機構及其代表人、負責人，或與該法人或機構有僱傭、委任或其他類似關係之人，不得為該受監護宣告之人之監護人。但為該受監護宣告之人之配偶、四親等內之血親或二親等內之姻親者，不在此限。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1100-1", "subject": "親屬法", "topic": "權利主體・§1100", "kind": "法條", "question": "【法條原文辨識】依《民法》第1100條，下列節錄的【空格】應填入何者？\n\n「【空格】應以善良管理人之注意，執行監護職務。」", "options": ["法定代理人", "代理人", "輔助人", "監護人"], "answer": 3, "explanations": ["此處不是「法定代理人」。民法第1100條在本題位置規定的是「監護人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「代理人」。民法第1100條在本題位置規定的是「監護人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「輔助人」。民法第1100條在本題位置規定的是「監護人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1100條此處原文是「監護人」。\n原句：監護人應以善良管理人之注意，執行監護職務。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第1100條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1100", "text": "監護人應以善良管理人之注意，執行監護職務。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1094-1-3", "subject": "親屬法", "topic": "親屬與繼承・§1094-1", "kind": "法條", "question": "【法條原文辨識】依《民法》第1094-1條，下列節錄的【空格】應填入何者？\n\n「二、【空格】人之年齡、職業、品行、意願、態度、健康情形、經濟能力、生活狀況及有無犯罪前科紀錄。」", "options": ["訂婚", "收養", "認領", "監護"], "answer": 3, "explanations": ["此處不是「訂婚」。民法第1094-1條在本題位置規定的是「監護」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「收養」。民法第1094-1條在本題位置規定的是「監護」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「認領」。民法第1094-1條在本題位置規定的是「監護」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1094-1條此處原文是「監護」。\n原句：二、監護人之年齡、職業、品行、意願、態度、健康情形、經濟能力、生活狀況及有無犯罪前科紀錄。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1094-1條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1094-1", "text": "法院選定或改定監護人時，應依受監護人之最佳利益，審酌一切情狀，尤應注意下列事項：\n一、受監護人之年齡、性別、意願、健康情形及人格發展需要。\n二、監護人之年齡、職業、品行、意願、態度、健康情形、經濟能力、生活狀況及有無犯罪前科紀錄。\n三、監護人與受監護人間或受監護人與其他共同生活之人間之情感及利害關係。\n四、法人為監護人時，其事業之種類與內容，法人及其代表人與受監護人之利害關係。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1137-1", "subject": "親屬法", "topic": "期間・數額・比例・§1137", "kind": "法條", "question": "【法條原文辨識】依《民法》第1137條，下列節錄的【空格】應填入何者？\n\n「第一千一百二十九條所定有召集權之人，對於親屬會議之決議有不服者，得於【空格】內向法院聲訴。」", "options": ["六個月", "三個月", "二個月", "一個月"], "answer": 1, "explanations": ["此處不是「六個月」。民法第1137條在本題位置規定的是「三個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1137條此處原文是「三個月」。\n原句：第一千一百二十九條所定有召集權之人，對於親屬會議之決議有不服者，得於三個月內向法院聲訴。", "此處不是「二個月」。民法第1137條在本題位置規定的是「三個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「一個月」。民法第1137條在本題位置規定的是「三個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1137條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1137", "text": "第一千一百二十九條所定有召集權之人，對於親屬會議之決議有不服者，得於三個月內向法院聲訴。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1032-2", "subject": "親屬法", "topic": "行政程序・§1032", "kind": "法條", "question": "【法條原文辨識】依《民法》第1032條，下列節錄的【空格】應填入何者？\n\n「共同財產之管理費用，由共同財產【空格】。」", "options": ["條件", "期限", "保留廢止權", "負擔"], "answer": 3, "explanations": ["此處不是「條件」。民法第1032條在本題位置規定的是「負擔」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「期限」。民法第1032條在本題位置規定的是「負擔」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「保留廢止權」。民法第1032條在本題位置規定的是「負擔」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1032條此處原文是「負擔」。\n原句：共同財產之管理費用，由共同財產負擔。"], "hint": "先判斷空格要填的是行政程序，再核對條件與例外。", "sources": [{"title": "民法第1032條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1032", "text": "共同財產，由夫妻共同管理。但約定由一方管理者，從其約定。\n共同財產之管理費用，由共同財產負擔。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1113-2-2", "subject": "親屬法", "topic": "期間・數額・比例・§1113-2", "kind": "法條", "question": "【法條原文辨識】依《民法》第1113-2條，下列節錄的【空格】應填入何者？\n\n「前項受任人得為【空格】或數人；其為數人者，除約定為分別執行職務外，應共同執行職務。」", "options": ["一人", "五人", "二人", "三人"], "answer": 0, "explanations": ["正確。民法第1113-2條此處原文是「一人」。\n原句：前項受任人得為一人或數人；其為數人者，除約定為分別執行職務外，應共同執行職務。", "此處不是「五人」。民法第1113-2條在本題位置規定的是「一人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「二人」。民法第1113-2條在本題位置規定的是「一人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「三人」。民法第1113-2條在本題位置規定的是「一人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1113-2條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1113-2", "text": "稱意定監護者，謂本人與受任人約定，於本人受監護宣告時，受任人允為擔任監護人之契約。\n前項受任人得為一人或數人；其為數人者，除約定為分別執行職務外，應共同執行職務。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1058-1", "subject": "親屬法", "topic": "親屬與繼承・§1058", "kind": "法條", "question": "【法條原文辨識】依《民法》第1058條，下列節錄的【空格】應填入何者？\n\n「夫妻離婚時，除採用【空格】者外，各自取回其結婚或變更夫妻財產制時之財產。如有剩餘，各依其夫妻財產制之規定分配之。」", "options": ["共同財產制", "法定財產制", "分別財產制", "剩餘財產分配制"], "answer": 2, "explanations": ["此處不是「共同財產制」。民法第1058條在本題位置規定的是「分別財產制」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「法定財產制」。民法第1058條在本題位置規定的是「分別財產制」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1058條此處原文是「分別財產制」。\n原句：夫妻離婚時，除採用分別財產制者外，各自取回其結婚或變更夫妻財產制時之財產。如有剩餘，各依其夫妻財產制之規定分配之。", "此處不是「剩餘財產分配制」。民法第1058條在本題位置規定的是「分別財產制」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1058條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1058", "text": "夫妻離婚時，除採用分別財產制者外，各自取回其結婚或變更夫妻財產制時之財產。如有剩餘，各依其夫妻財產制之規定分配之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-999-2", "subject": "親屬法", "topic": "犯罪與責任・§999", "kind": "法條", "question": "【法條原文辨識】依《民法》第999條，下列節錄的【空格】應填入何者？\n\n「前項情形，雖非財產上之損害，受害人亦得請求賠償相當之金額。但以受害人無【空格】者為限。」", "options": ["故意", "正當防衛", "過失", "緊急避難"], "answer": 2, "explanations": ["此處不是「故意」。民法第999條在本題位置規定的是「過失」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「正當防衛」。民法第999條在本題位置規定的是「過失」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第999條此處原文是「過失」。\n原句：前項情形，雖非財產上之損害，受害人亦得請求賠償相當之金額。但以受害人無過失者為限。", "此處不是「緊急避難」。民法第999條在本題位置規定的是「過失」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是犯罪與責任，再核對條件與例外。", "sources": [{"title": "民法第999條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=999", "text": "當事人之一方，因結婚無效或被撤銷而受有損害者，得向他方請求賠償。但他方無過失者，不在此限。\n前項情形，雖非財產上之損害，受害人亦得請求賠償相當之金額。但以受害人無過失者為限。\n前項請求權，不得讓與或繼承。但已依契約承諾或已起訴者，不在此限。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1002-1", "subject": "親屬法", "topic": "憲政原則・§1002", "kind": "法條", "question": "【法條原文辨識】依《民法》第1002條，下列節錄的【空格】應填入何者？\n\n「夫妻之【空格】，由雙方共同協議之；未為協議或協議不成時，得聲請法院定之。」", "options": ["住所", "戶籍", "國籍", "出生地"], "answer": 0, "explanations": ["正確。民法第1002條此處原文是「住所」。\n原句：夫妻之住所，由雙方共同協議之；未為協議或協議不成時，得聲請法院定之。", "此處不是「戶籍」。民法第1002條在本題位置規定的是「住所」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「國籍」。民法第1002條在本題位置規定的是「住所」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「出生地」。民法第1002條在本題位置規定的是「住所」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是憲政原則，再核對條件與例外。", "sources": [{"title": "民法第1002條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1002", "text": "夫妻之住所，由雙方共同協議之；未為協議或協議不成時，得聲請法院定之。\n法院為前項裁定前，以夫妻共同戶籍地推定為其住所。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-972-1", "subject": "親屬法", "topic": "親屬與繼承・§972", "kind": "法條", "question": "【法條原文辨識】依《民法》第972條，下列節錄的【空格】應填入何者？\n\n「【空格】，應由男女當事人自行訂定。」", "options": ["離婚", "收養", "婚約", "結婚"], "answer": 2, "explanations": ["此處不是「離婚」。民法第972條在本題位置規定的是「婚約」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「收養」。民法第972條在本題位置規定的是「婚約」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第972條此處原文是「婚約」。\n原句：婚約，應由男女當事人自行訂定。", "此處不是「結婚」。民法第972條在本題位置規定的是「婚約」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第972條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=972", "text": "婚約，應由男女當事人自行訂定。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1080-2-1", "subject": "親屬法", "topic": "法律效果・§1080-2", "kind": "法條", "question": "【法條原文辨識】依《民法》第1080-2條，下列節錄的【空格】應填入何者？\n\n「終止收養，違反第一千零八十條第二項、第五項或第一千零八十條之一第二項規定者，【空格】。」", "options": ["有效", "無效", "效力未定", "得撤銷"], "answer": 1, "explanations": ["此處不是「有效」。民法第1080-2條在本題位置規定的是「無效」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1080-2條此處原文是「無效」。\n原句：終止收養，違反第一千零八十條第二項、第五項或第一千零八十條之一第二項規定者，無效。", "此處不是「效力未定」。民法第1080-2條在本題位置規定的是「無效」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「得撤銷」。民法第1080-2條在本題位置規定的是「無效」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是法律效果，再核對條件與例外。", "sources": [{"title": "民法第1080-2條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1080-2", "text": "終止收養，違反第一千零八十條第二項、第五項或第一千零八十條之一第二項規定者，無效。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1109-1-1", "subject": "親屬法", "topic": "親屬與繼承・§1109-1", "kind": "法條", "question": "【法條原文辨識】依《民法》第1109-1條，下列節錄的【空格】應填入何者？\n\n「【空格】於選定監護人、許可監護人辭任及另行選定或改定監護人時，應依職權囑託該管戶政機關登記。」", "options": ["親屬會議", "戶政機關", "檢察官", "法院"], "answer": 3, "explanations": ["此處不是「親屬會議」。民法第1109-1條在本題位置規定的是「法院」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「戶政機關」。民法第1109-1條在本題位置規定的是「法院」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「檢察官」。民法第1109-1條在本題位置規定的是「法院」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1109-1條此處原文是「法院」。\n原句：法院於選定監護人、許可監護人辭任及另行選定或改定監護人時，應依職權囑託該管戶政機關登記。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1109-1條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1109-1", "text": "法院於選定監護人、許可監護人辭任及另行選定或改定監護人時，應依職權囑託該管戶政機關登記。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1055-1-9", "subject": "親屬法", "topic": "權限主體・§1055-1", "kind": "法條", "question": "【法條原文辨識】依《民法》第1055-1條，下列節錄的【空格】應填入何者？\n\n「前項子女最佳利益之審酌，法院除得參考社工人員之訪視報告或家事調查官之調查報告外，並得依囑託【空格】機關、稅捐機關、金融機構、學校及其他有關機關、團體或具有相關專業知識之適當人士就特定事項調查之結果認定之。」", "options": ["檢察官", "警察", "法官", "律師"], "answer": 1, "explanations": ["此處不是「檢察官」。民法第1055-1條在本題位置規定的是「警察」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1055-1條此處原文是「警察」。\n原句：前項子女最佳利益之審酌，法院除得參考社工人員之訪視報告或家事調查官之調查報告外，並得依囑託警察機關、稅捐機關、金融機構、學校及其他有關機關、團體或具有相關專業知識之適當人士就特定事項調查之結果認定之。", "此處不是「法官」。民法第1055-1條在本題位置規定的是「警察」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「律師」。民法第1055-1條在本題位置規定的是「警察」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權限主體，再核對條件與例外。", "sources": [{"title": "民法第1055-1條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1055-1", "text": "法院為前條裁判時，應依子女之最佳利益，審酌一切情狀，尤應注意下列事項：\n一、子女之年齡、性別、人數及健康情形。\n二、子女之意願及人格發展之需要。\n三、父母之年齡、職業、品行、健康情形、經濟能力及生活狀況。\n四、父母保護教養子女之意願及態度。\n五、父母子女間或未成年子女與其他共同生活之人間之感情狀況。\n六、父母之一方是否有妨礙他方對未成年子女權利義務行使負擔之行為。\n七、各族群之傳統習俗、文化及價值觀。\n前項子女最佳利益之審酌，法院除得參考社工人員之訪視報告或家事調查官之調查報告外，並得依囑託警察機關、稅捐機關、金融機構、學校及其他有關機關、團體或具有相關專業知識之適當人士就特定事項調查之結果認定之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-983-6", "subject": "親屬法", "topic": "法律效果・§983", "kind": "法條", "question": "【法條原文辨識】依《民法》第983條，下列節錄的【空格】應填入何者？\n\n「第一項直系血親及直系姻親結婚之限制，於因收養而成立之直系親屬間，在收養關係【空格】後，亦適用之。」", "options": ["終止", "解除", "撤銷", "變更"], "answer": 0, "explanations": ["正確。民法第983條此處原文是「終止」。\n原句：第一項直系血親及直系姻親結婚之限制，於因收養而成立之直系親屬間，在收養關係終止後，亦適用之。", "此處不是「解除」。民法第983條在本題位置規定的是「終止」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「撤銷」。民法第983條在本題位置規定的是「終止」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「變更」。民法第983條在本題位置規定的是「終止」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是法律效果，再核對條件與例外。", "sources": [{"title": "民法第983條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=983", "text": "與左列親屬，不得結婚︰\n一、直系血親及直系姻親。\n二、旁系血親在六親等以內者。但因收養而成立之四親等及六親等旁系血親，輩分相同者，不在此限。\n三、旁系姻親在五親等以內，輩分不相同者。\n前項直系姻親結婚之限制，於姻親關係消滅後，亦適用之。\n第一項直系血親及直系姻親結婚之限制，於因收養而成立之直系親屬間，在收養關係終止後，亦適用之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1076-1", "subject": "親屬法", "topic": "期間・數額・比例・§1076", "kind": "法條", "question": "【法條原文辨識】依《民法》第1076條，下列節錄的【空格】應填入何者？\n\n「夫妻之一方被收養時，應得他方之同意。但他方不能為意思表示或生死不明已逾【空格】者，不在此限。」", "options": ["五年", "二年", "一年", "三年"], "answer": 3, "explanations": ["此處不是「五年」。民法第1076條在本題位置規定的是「三年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「二年」。民法第1076條在本題位置規定的是「三年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「一年」。民法第1076條在本題位置規定的是「三年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1076條此處原文是「三年」。\n原句：夫妻之一方被收養時，應得他方之同意。但他方不能為意思表示或生死不明已逾三年者，不在此限。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1076條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1076", "text": "夫妻之一方被收養時，應得他方之同意。但他方不能為意思表示或生死不明已逾三年者，不在此限。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1063-2", "subject": "親屬法", "topic": "親屬與繼承・§1063", "kind": "法條", "question": "【法條原文辨識】依《民法》第1063條，下列節錄的【空格】應填入何者？\n\n「前項推定，夫妻之一方或子女能證明子女非為【空格】者，得提起否認之訴。」", "options": ["繼子女", "婚生子女", "非婚生子女", "養子女"], "answer": 1, "explanations": ["此處不是「繼子女」。民法第1063條在本題位置規定的是「婚生子女」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1063條此處原文是「婚生子女」。\n原句：前項推定，夫妻之一方或子女能證明子女非為婚生子女者，得提起否認之訴。", "此處不是「非婚生子女」。民法第1063條在本題位置規定的是「婚生子女」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「養子女」。民法第1063條在本題位置規定的是「婚生子女」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1063條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1063", "text": "妻之受胎，係在婚姻關係存續中者，推定其所生子女為婚生子女。\n前項推定，夫妻之一方或子女能證明子女非為婚生子女者，得提起否認之訴。\n前項否認之訴，夫妻之一方自知悉該子女非為婚生子女，或子女自知悉其非為婚生子女之時起二年內為之。但子女於未成年時知悉者，仍得於成年後二年內為之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1083-1", "subject": "親屬法", "topic": "憲政原則・§1083", "kind": "法條", "question": "【法條原文辨識】依《民法》第1083條，下列節錄的【空格】應填入何者？\n\n「養子女及收養效力所及之直系血親卑親屬，自收養關係終止時起，回復其本姓，並回復其與本生父母及其親屬間之權利【空格】。但第三人已取得之權利，不受影響。」", "options": ["自由", "資格", "義務", "責任"], "answer": 2, "explanations": ["此處不是「自由」。民法第1083條在本題位置規定的是「義務」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「資格」。民法第1083條在本題位置規定的是「義務」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1083條此處原文是「義務」。\n原句：養子女及收養效力所及之直系血親卑親屬，自收養關係終止時起，回復其本姓，並回復其與本生父母及其親屬間之權利義務。但第三人已取得之權利，不受影響。", "此處不是「責任」。民法第1083條在本題位置規定的是「義務」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是憲政原則，再核對條件與例外。", "sources": [{"title": "民法第1083條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1083", "text": "養子女及收養效力所及之直系血親卑親屬，自收養關係終止時起，回復其本姓，並回復其與本生父母及其親屬間之權利義務。但第三人已取得之權利，不受影響。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1056-2", "subject": "親屬法", "topic": "犯罪與責任・§1056", "kind": "法條", "question": "【法條原文辨識】依《民法》第1056條，下列節錄的【空格】應填入何者？\n\n「前項情形，雖非財產上之損害，受害人亦得請求賠償相當之金額。但以受害人無【空格】者為限。」", "options": ["過失", "正當防衛", "緊急避難", "故意"], "answer": 0, "explanations": ["正確。民法第1056條此處原文是「過失」。\n原句：前項情形，雖非財產上之損害，受害人亦得請求賠償相當之金額。但以受害人無過失者為限。", "此處不是「正當防衛」。民法第1056條在本題位置規定的是「過失」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「緊急避難」。民法第1056條在本題位置規定的是「過失」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「故意」。民法第1056條在本題位置規定的是「過失」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是犯罪與責任，再核對條件與例外。", "sources": [{"title": "民法第1056條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1056", "text": "夫妻之一方，因判決離婚而受有損害者，得向有過失之他方，請求賠償。\n前項情形，雖非財產上之損害，受害人亦得請求賠償相當之金額。但以受害人無過失者為限。\n前項請求權，不得讓與或繼承。但已依契約承諾或已起訴者，不在此限。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1079-4-1", "subject": "親屬法", "topic": "法律效果・§1079-4", "kind": "法條", "question": "【法條原文辨識】依《民法》第1079-4條，下列節錄的【空格】應填入何者？\n\n「收養子女，違反第一千零七十三條、第一千零七十三條之一、第一千零七十五條、第一千零七十六條之一、第一千零七十六條之二第一項或第一千零七十九條第一項之規定者，【空格】。」", "options": ["有效", "無效", "效力未定", "得撤銷"], "answer": 1, "explanations": ["此處不是「有效」。民法第1079-4條在本題位置規定的是「無效」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1079-4條此處原文是「無效」。\n原句：收養子女，違反第一千零七十三條、第一千零七十三條之一、第一千零七十五條、第一千零七十六條之一、第一千零七十六條之二第一項或第一千零七十九條第一項之規定者，無效。", "此處不是「效力未定」。民法第1079-4條在本題位置規定的是「無效」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「得撤銷」。民法第1079-4條在本題位置規定的是「無效」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是法律效果，再核對條件與例外。", "sources": [{"title": "民法第1079-4條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1079-4", "text": "收養子女，違反第一千零七十三條、第一千零七十三條之一、第一千零七十五條、第一千零七十六條之一、第一千零七十六條之二第一項或第一千零七十九條第一項之規定者，無效。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1091-1", "subject": "親屬法", "topic": "憲政原則・§1091", "kind": "法條", "question": "【法條原文辨識】依《民法》第1091條，下列節錄的【空格】應填入何者？\n\n「未成年人無父母，或父母均不能行使、負擔對於其未成年子女之權利、【空格】時，應置監護人。」", "options": ["自由", "義務", "資格", "責任"], "answer": 1, "explanations": ["此處不是「自由」。民法第1091條在本題位置規定的是「義務」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1091條此處原文是「義務」。\n原句：未成年人無父母，或父母均不能行使、負擔對於其未成年子女之權利、義務時，應置監護人。", "此處不是「資格」。民法第1091條在本題位置規定的是「義務」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「責任」。民法第1091條在本題位置規定的是「義務」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是憲政原則，再核對條件與例外。", "sources": [{"title": "民法第1091條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1091", "text": "未成年人無父母，或父母均不能行使、負擔對於其未成年子女之權利、義務時，應置監護人。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1077-5", "subject": "親屬法", "topic": "法律要件・§1077", "kind": "法條", "question": "【法條原文辨識】依《民法》第1077條，下列節錄的【空格】應填入何者？\n\n「前項【空格】，準用第一千零七十六條之一第二項及第三項之規定。」", "options": ["承認", "許可", "通知", "同意"], "answer": 3, "explanations": ["此處不是「承認」。民法第1077條在本題位置規定的是「同意」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「許可」。民法第1077條在本題位置規定的是「同意」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「通知」。民法第1077條在本題位置規定的是「同意」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1077條此處原文是「同意」。\n原句：前項同意，準用第一千零七十六條之一第二項及第三項之規定。"], "hint": "先判斷空格要填的是法律要件，再核對條件與例外。", "sources": [{"title": "民法第1077條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1077", "text": "養子女與養父母及其親屬間之關係，除法律另有規定外，與婚生子女同。\n養子女與本生父母及其親屬間之權利義務，於收養關係存續中停止之。但夫妻之一方收養他方之子女時，他方與其子女之權利義務，不因收養而受影響。\n收養者收養子女後，與養子女之本生父或母結婚時，養子女回復與本生父或母及其親屬間之權利義務。但第三人已取得之權利，不受影響。\n養子女於收養認可時已有直系血親卑親屬者，收養之效力僅及於其未成年之直系血親卑親屬。但收養認可前，其已成年之直系血親卑親屬表示同意者，不在此限。\n前項同意，準用第一千零七十六條之一第二項及第三項之規定。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1089-1-1", "subject": "親屬法", "topic": "期間・數額・比例・§1089-1", "kind": "法條", "question": "【法條原文辨識】依《民法》第1089-1條，下列節錄的【空格】應填入何者？\n\n「父母不繼續共同生活達【空格】以上時，關於未成年子女權利義務之行使或負擔，準用第一千零五十五條、第一千零五十五條之一及第一千零五十五條之二之規定。但父母有不能同居之正當理由或法律另有規定者，不在此限。」", "options": ["三個月", "一個月", "六個月", "二個月"], "answer": 2, "explanations": ["此處不是「三個月」。民法第1089-1條在本題位置規定的是「六個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「一個月」。民法第1089-1條在本題位置規定的是「六個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1089-1條此處原文是「六個月」。\n原句：父母不繼續共同生活達六個月以上時，關於未成年子女權利義務之行使或負擔，準用第一千零五十五條、第一千零五十五條之一及第一千零五十五條之二之規定。但父母有不能同居之正當理由或法律另有規定者，不在此限。", "此處不是「二個月」。民法第1089-1條在本題位置規定的是「六個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1089-1條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1089-1", "text": "父母不繼續共同生活達六個月以上時，關於未成年子女權利義務之行使或負擔，準用第一千零五十五條、第一千零五十五條之一及第一千零五十五條之二之規定。但父母有不能同居之正當理由或法律另有規定者，不在此限。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1064-1", "subject": "親屬法", "topic": "親屬與繼承・§1064", "kind": "法條", "question": "【法條原文辨識】依《民法》第1064條，下列節錄的【空格】應填入何者？\n\n「非婚生子女，其生父與生母【空格】者，視為婚生子女。」", "options": ["收養", "離婚", "婚約", "結婚"], "answer": 3, "explanations": ["此處不是「收養」。民法第1064條在本題位置規定的是「結婚」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「離婚」。民法第1064條在本題位置規定的是「結婚」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「婚約」。民法第1064條在本題位置規定的是「結婚」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1064條此處原文是「結婚」。\n原句：非婚生子女，其生父與生母結婚者，視為婚生子女。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1064條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1064", "text": "非婚生子女，其生父與生母結婚者，視為婚生子女。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1076-2-2", "subject": "親屬法", "topic": "期間・數額・比例・§1076-2", "kind": "法條", "question": "【法條原文辨識】依《民法》第1076-2條，下列節錄的【空格】應填入何者？\n\n「滿【空格】以上之未成年人被收養時，應得其法定代理人之同意。」", "options": ["十四歲", "七歲", "十七歲", "十六歲"], "answer": 1, "explanations": ["此處不是「十四歲」。民法第1076-2條在本題位置規定的是「七歲」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1076-2條此處原文是「七歲」。\n原句：滿七歲以上之未成年人被收養時，應得其法定代理人之同意。", "此處不是「十七歲」。民法第1076-2條在本題位置規定的是「七歲」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「十六歲」。民法第1076-2條在本題位置規定的是「七歲」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1076-2條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1076-2", "text": "被收養者未滿七歲時，應由其法定代理人代為並代受意思表示。\n滿七歲以上之未成年人被收養時，應得其法定代理人之同意。\n被收養者之父母已依前二項規定以法定代理人之身分代為並代受意思表示或為同意時，得免依前條規定為同意。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1116-2-1", "subject": "親屬法", "topic": "親屬與繼承・§1116-2", "kind": "法條", "question": "【法條原文辨識】依《民法》第1116-2條，下列節錄的【空格】應填入何者？\n\n「【空格】對於未成年子女之扶養義務，不因結婚經撤銷或離婚而受影響。」", "options": ["直系血親卑親屬", "兄弟姊妹", "父母", "祖父母"], "answer": 2, "explanations": ["此處不是「直系血親卑親屬」。民法第1116-2條在本題位置規定的是「父母」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「兄弟姊妹」。民法第1116-2條在本題位置規定的是「父母」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1116-2條此處原文是「父母」。\n原句：父母對於未成年子女之扶養義務，不因結婚經撤銷或離婚而受影響。", "此處不是「祖父母」。民法第1116-2條在本題位置規定的是「父母」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1116-2條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1116-2", "text": "父母對於未成年子女之扶養義務，不因結婚經撤銷或離婚而受影響。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-985-2", "subject": "親屬法", "topic": "期間・數額・比例・§985", "kind": "法條", "question": "【法條原文辨識】依《民法》第985條，下列節錄的【空格】應填入何者？\n\n「【空格】不得同時與二人以上結婚。」", "options": ["一人", "二人", "三人", "五人"], "answer": 0, "explanations": ["正確。民法第985條此處原文是「一人」。\n原句：一人不得同時與二人以上結婚。", "此處不是「二人」。民法第985條在本題位置規定的是「一人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「三人」。民法第985條在本題位置規定的是「一人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「五人」。民法第985條在本題位置規定的是「一人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第985條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=985", "text": "有配偶者，不得重婚。\n一人不得同時與二人以上結婚。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1001-1", "subject": "親屬法", "topic": "憲政原則・§1001", "kind": "法條", "question": "【法條原文辨識】依《民法》第1001條，下列節錄的【空格】應填入何者？\n\n「夫妻互負同居之【空格】。但有不能同居之正當理由者，不在此限。」", "options": ["資格", "義務", "責任", "自由"], "answer": 1, "explanations": ["此處不是「資格」。民法第1001條在本題位置規定的是「義務」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1001條此處原文是「義務」。\n原句：夫妻互負同居之義務。但有不能同居之正當理由者，不在此限。", "此處不是「責任」。民法第1001條在本題位置規定的是「義務」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「自由」。民法第1001條在本題位置規定的是「義務」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是憲政原則，再核對條件與例外。", "sources": [{"title": "民法第1001條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1001", "text": "夫妻互負同居之義務。但有不能同居之正當理由者，不在此限。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1112-1-2", "subject": "親屬法", "topic": "法律效果・§1112-1", "kind": "法條", "question": "【法條原文辨識】依《民法》第1112-1條，下列節錄的【空格】應填入何者？\n\n「法院得因監護人、受監護人、第十四條第一項聲請權人之聲請，【空格】或變更前項之指定。」", "options": ["撤銷", "解除", "終止", "變更"], "answer": 0, "explanations": ["正確。民法第1112-1條此處原文是「撤銷」。\n原句：法院得因監護人、受監護人、第十四條第一項聲請權人之聲請，撤銷或變更前項之指定。", "此處不是「解除」。民法第1112-1條在本題位置規定的是「撤銷」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「終止」。民法第1112-1條在本題位置規定的是「撤銷」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「變更」。民法第1112-1條在本題位置規定的是「撤銷」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是法律效果，再核對條件與例外。", "sources": [{"title": "民法第1112-1條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1112-1", "text": "法院選定數人為監護人時，得依職權指定其共同或分別執行職務之範圍。\n法院得因監護人、受監護人、第十四條第一項聲請權人之聲請，撤銷或變更前項之指定。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1116-1-1", "subject": "親屬法", "topic": "親屬與繼承・§1116-1", "kind": "法條", "question": "【法條原文辨識】依《民法》第1116-1條，下列節錄的【空格】應填入何者？\n\n「夫妻互負扶養之義務，其負扶養義務之順序與【空格】同，其受扶養權利之順序與直系血親尊親屬同。」", "options": ["兄弟姊妹", "祖父母", "直系血親卑親屬", "父母"], "answer": 2, "explanations": ["此處不是「兄弟姊妹」。民法第1116-1條在本題位置規定的是「直系血親卑親屬」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「祖父母」。民法第1116-1條在本題位置規定的是「直系血親卑親屬」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1116-1條此處原文是「直系血親卑親屬」。\n原句：夫妻互負扶養之義務，其負扶養義務之順序與直系血親卑親屬同，其受扶養權利之順序與直系血親尊親屬同。", "此處不是「父母」。民法第1116-1條在本題位置規定的是「直系血親卑親屬」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1116-1條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1116-1", "text": "夫妻互負扶養之義務，其負扶養義務之順序與直系血親卑親屬同，其受扶養權利之順序與直系血親尊親屬同。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1113-1-1", "subject": "親屬法", "topic": "權利主體・§1113-1", "kind": "法條", "question": "【法條原文辨識】依《民法》第1113-1條，下列節錄的【空格】應填入何者？\n\n「受輔助宣告之人，應置【空格】。」", "options": ["代理人", "輔助人", "監護人", "法定代理人"], "answer": 1, "explanations": ["此處不是「代理人」。民法第1113-1條在本題位置規定的是「輔助人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1113-1條此處原文是「輔助人」。\n原句：受輔助宣告之人，應置輔助人。", "此處不是「監護人」。民法第1113-1條在本題位置規定的是「輔助人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「法定代理人」。民法第1113-1條在本題位置規定的是「輔助人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第1113-1條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1113-1", "text": "受輔助宣告之人，應置輔助人。\n輔助人及有關輔助之職務，準用第一千零九十五條、第一千零九十六條、第一千零九十八條第二項、第一千一百條、第一千一百零二條、第一千一百零三條第二項、第一千一百零四條、第一千一百零六條、第一千一百零六條之一、第一千一百零九條、第一千一百十一條至第一千一百十一條之二、第一千一百十二條之一及第一千一百十二條之二之規定。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1078-1", "subject": "親屬法", "topic": "親屬與繼承・§1078", "kind": "法條", "question": "【法條原文辨識】依《民法》第1078條，下列節錄的【空格】應填入何者？\n\n「養子女從【空格】者之姓或維持原來之姓。」", "options": ["結婚", "收養", "離婚", "婚約"], "answer": 1, "explanations": ["此處不是「結婚」。民法第1078條在本題位置規定的是「收養」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1078條此處原文是「收養」。\n原句：養子女從收養者之姓或維持原來之姓。", "此處不是「離婚」。民法第1078條在本題位置規定的是「收養」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「婚約」。民法第1078條在本題位置規定的是「收養」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1078條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1078", "text": "養子女從收養者之姓或維持原來之姓。\n夫妻共同收養子女時，於收養登記前，應以書面約定養子女從養父姓、養母姓或維持原來之姓。\n第一千零五十九條第二項至第五項之規定，於收養之情形準用之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-A0030055-153-4", "subject": "行政法", "topic": "憲政原則・§153", "kind": "法條", "question": "【法條原文辨識】依《行政程序法》第153條，下列節錄的【空格】應填入何者？\n\n「三、無須訂定法規【空格】之事項，附述理由通知原提議者。」", "options": ["法理", "習慣", "命令", "法律"], "answer": 2, "explanations": ["此處不是「法理」。行政程序法第153條在本題位置規定的是「命令」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「習慣」。行政程序法第153條在本題位置規定的是「命令」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。行政程序法第153條此處原文是「命令」。\n原句：三、無須訂定法規命令之事項，附述理由通知原提議者。", "此處不是「法律」。行政程序法第153條在本題位置規定的是「命令」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是憲政原則，再核對條件與例外。", "sources": [{"title": "行政程序法第153條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=A0030055&flno=153", "text": "受理前條提議之行政機關，應依下列情形分別處理︰\n一、非主管之事項，依第十七條之規定予以移送。\n二、依法不得以法規命令規定之事項，附述理由通知原提議者。\n三、無須訂定法規命令之事項，附述理由通知原提議者。\n四、有訂定法規命令之必要者，著手研擬草案。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-A0030055-122-1", "subject": "行政法", "topic": "犯罪與責任・§122", "kind": "法條", "question": "【法條原文辨識】依《行政程序法》第122條，下列節錄的【空格】應填入何者？\n\n「非授予利益之合法【空格】，得由原處分機關依職權為全部或一部之廢止。但廢止後仍應為同一內容之處分或依法不得廢止者，不在此限。」", "options": ["保安處分", "行政處分", "懲戒處分", "緩刑"], "answer": 1, "explanations": ["此處不是「保安處分」。行政程序法第122條在本題位置規定的是「行政處分」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。行政程序法第122條此處原文是「行政處分」。\n原句：非授予利益之合法行政處分，得由原處分機關依職權為全部或一部之廢止。但廢止後仍應為同一內容之處分或依法不得廢止者，不在此限。", "此處不是「懲戒處分」。行政程序法第122條在本題位置規定的是「行政處分」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「緩刑」。行政程序法第122條在本題位置規定的是「行政處分」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是犯罪與責任，再核對條件與例外。", "sources": [{"title": "行政程序法第122條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=A0030055&flno=122", "text": "非授予利益之合法行政處分，得由原處分機關依職權為全部或一部之廢止。但廢止後仍應為同一內容之處分或依法不得廢止者，不在此限。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-A0030055-41-2", "subject": "行政法", "topic": "債的效力・§41", "kind": "法條", "question": "【法條原文辨識】依《行政程序法》第41條，下列節錄的【空格】應填入何者？\n\n「以書面為鑑定者，必要時，得【空格】鑑定人到場說明。」", "options": ["通知", "承認", "撤回", "拒絕"], "answer": 0, "explanations": ["正確。行政程序法第41條此處原文是「通知」。\n原句：以書面為鑑定者，必要時，得通知鑑定人到場說明。", "此處不是「承認」。行政程序法第41條在本題位置規定的是「通知」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「撤回」。行政程序法第41條在本題位置規定的是「通知」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「拒絕」。行政程序法第41條在本題位置規定的是「通知」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是債的效力，再核對條件與例外。", "sources": [{"title": "行政程序法第41條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=A0030055&flno=41", "text": "行政機關得選定適當之人為鑑定。\n以書面為鑑定者，必要時，得通知鑑定人到場說明。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-A0030055-70-1", "subject": "行政法", "topic": "憲政原則・§70", "kind": "法條", "question": "【法條原文辨識】依《行政程序法》第70條，下列節錄的【空格】應填入何者？\n\n「對於在中華民國有事務所或營業所之外國法人或【空格】為送達者，應向其在中華民國之代表人或管理人為之。」", "options": ["法院", "團體", "學校", "政黨"], "answer": 1, "explanations": ["此處不是「法院」。行政程序法第70條在本題位置規定的是「團體」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。行政程序法第70條此處原文是「團體」。\n原句：對於在中華民國有事務所或營業所之外國法人或團體為送達者，應向其在中華民國之代表人或管理人為之。", "此處不是「學校」。行政程序法第70條在本題位置規定的是「團體」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「政黨」。行政程序法第70條在本題位置規定的是「團體」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是憲政原則，再核對條件與例外。", "sources": [{"title": "行政程序法第70條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=A0030055&flno=70", "text": "對於在中華民國有事務所或營業所之外國法人或團體為送達者，應向其在中華民國之代表人或管理人為之。\n前條第三項規定，於前項送達準用之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-A0030055-155-1", "subject": "行政法", "topic": "行政程序・§155", "kind": "法條", "question": "【法條原文辨識】依《行政程序法》第155條，下列節錄的【空格】應填入何者？\n\n「行政機關訂定【空格】，得依職權舉行聽證。」", "options": ["行政計畫", "法規命令", "行政指導", "行政規則"], "answer": 1, "explanations": ["此處不是「行政計畫」。行政程序法第155條在本題位置規定的是「法規命令」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。行政程序法第155條此處原文是「法規命令」。\n原句：行政機關訂定法規命令，得依職權舉行聽證。", "此處不是「行政指導」。行政程序法第155條在本題位置規定的是「法規命令」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「行政規則」。行政程序法第155條在本題位置規定的是「法規命令」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是行政程序，再核對條件與例外。", "sources": [{"title": "行政程序法第155條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=A0030055&flno=155", "text": "行政機關訂定法規命令，得依職權舉行聽證。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-A0030055-164-1", "subject": "行政法", "topic": "權限主體・§164", "kind": "法條", "question": "【法條原文辨識】依《行政程序法》第164條，下列節錄的【空格】應填入何者？\n\n「行政計畫有關一定地區土地之特定利用或重大公共設施之設置，涉及多數不同利益之人及多數不同【空格】權限者，確定其計畫之裁決，應經公開及聽證程序，並得有集中事權之效果。」", "options": ["法院", "警察機關", "行政機關", "檢察官"], "answer": 2, "explanations": ["此處不是「法院」。行政程序法第164條在本題位置規定的是「行政機關」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「警察機關」。行政程序法第164條在本題位置規定的是「行政機關」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。行政程序法第164條此處原文是「行政機關」。\n原句：行政計畫有關一定地區土地之特定利用或重大公共設施之設置，涉及多數不同利益之人及多數不同行政機關權限者，確定其計畫之裁決，應經公開及聽證程序，並得有集中事權之效果。", "此處不是「檢察官」。行政程序法第164條在本題位置規定的是「行政機關」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權限主體，再核對條件與例外。", "sources": [{"title": "行政程序法第164條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=A0030055&flno=164", "text": "行政計畫有關一定地區土地之特定利用或重大公共設施之設置，涉及多數不同利益之人及多數不同行政機關權限者，確定其計畫之裁決，應經公開及聽證程序，並得有集中事權之效果。\n前項行政計畫之擬訂、確定、修訂及廢棄之程序，由行政院另定之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-A0030055-121-2", "subject": "行政法", "topic": "期間・數額・比例・§121", "kind": "法條", "question": "【法條原文辨識】依《行政程序法》第121條，下列節錄的【空格】應填入何者？\n\n「前條之補償請求權，自行政機關告知其事由時起，因二年間不行使而消滅；自處分撤銷時起逾【空格】者，亦同。」", "options": ["二年", "三年", "五年", "一年"], "answer": 2, "explanations": ["此處不是「二年」。行政程序法第121條在本題位置規定的是「五年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「三年」。行政程序法第121條在本題位置規定的是「五年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。行政程序法第121條此處原文是「五年」。\n原句：前條之補償請求權，自行政機關告知其事由時起，因二年間不行使而消滅；自處分撤銷時起逾五年者，亦同。", "此處不是「一年」。行政程序法第121條在本題位置規定的是「五年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "行政程序法第121條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=A0030055&flno=121", "text": "第一百十七條之撤銷權，應自原處分機關或其上級機關知有撤銷原因時起二年內為之。\n前條之補償請求權，自行政機關告知其事由時起，因二年間不行使而消滅；自處分撤銷時起逾五年者，亦同。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-A0030055-91-1", "subject": "行政法", "topic": "憲政原則・§91", "kind": "法條", "question": "【法條原文辨識】依《行政程序法》第91條，下列節錄的【空格】應填入何者？\n\n「受囑託之機關或公務員，經通知已為送達或不能為送達者，【空格】機關應將通知書附卷。」", "options": ["司法", "立法", "行政", "監察"], "answer": 2, "explanations": ["此處不是「司法」。行政程序法第91條在本題位置規定的是「行政」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「立法」。行政程序法第91條在本題位置規定的是「行政」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。行政程序法第91條此處原文是「行政」。\n原句：受囑託之機關或公務員，經通知已為送達或不能為送達者，行政機關應將通知書附卷。", "此處不是「監察」。行政程序法第91條在本題位置規定的是「行政」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是憲政原則，再核對條件與例外。", "sources": [{"title": "行政程序法第91條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=A0030055&flno=91", "text": "受囑託之機關或公務員，經通知已為送達或不能為送達者，行政機關應將通知書附卷。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-A0030055-31-3", "subject": "行政法", "topic": "憲政原則・§31", "kind": "法條", "question": "【法條原文辨識】依《行政程序法》第31條，下列節錄的【空格】應填入何者？\n\n「前二項之輔佐人，【空格】機關認為不適當時，得撤銷其許可或禁止其陳述。」", "options": ["行政", "監察", "司法", "立法"], "answer": 0, "explanations": ["正確。行政程序法第31條此處原文是「行政」。\n原句：前二項之輔佐人，行政機關認為不適當時，得撤銷其許可或禁止其陳述。", "此處不是「監察」。行政程序法第31條在本題位置規定的是「行政」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「司法」。行政程序法第31條在本題位置規定的是「行政」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「立法」。行政程序法第31條在本題位置規定的是「行政」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是憲政原則，再核對條件與例外。", "sources": [{"title": "行政程序法第31條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=A0030055&flno=31", "text": "當事人或代理人經行政機關之許可，得偕同輔佐人到場。\n行政機關認為必要時，得命當事人或代理人偕同輔佐人到場。\n前二項之輔佐人，行政機關認為不適當時，得撤銷其許可或禁止其陳述。\n輔佐人所為之陳述，當事人或代理人未立即提出異議者，視為其所自為。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}]);
